// Static preview shell only. Never cache provider calls or customer/order APIs.
const CACHE='racharla-preview-shell-v8';
const CORE=['/','/index.html','/style.css','/app.js','/retail-rules.js','/inventory-rules.js','/content-rules.js','/commerce-rules.js','/order-rules.js','/store-config.js','/entry.js','/pwa.js','/manifest.webmanifest','/app-icon.svg'];
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);for(const path of CORE){try{const r=await fetch(path,{cache:'reload'});if(r.ok&&!r.redirected)await cache.put(path,r);}catch{}}})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('racharla-preview-shell-')&&key!==CACHE)await caches.delete(key);await self.clients.claim();})()));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!CORE.includes(url.pathname)||url.search)return;event.respondWith((async()=>{try{const response=await fetch(event.request);if(response.ok&&!response.redirected){const cache=await caches.open(CACHE);await cache.put(url.pathname,response.clone());}return response;}catch{const cached=await caches.match(url.pathname);return cached||new Response('Offline. Reconnect to load the store.',{status:503,headers:{'Content-Type':'text/plain'}});}})());});
